from pathlib import Path
import subprocess,json,hashlib,datetime
root=Path('/workspace/room18-circuits-native');repo=Path('/workspace/containment-room18-review');m=json.loads((root/'manifest.json').read_text());hashfile=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
current=[{'path':r['path'],'sha256':hashfile(repo/r['path'])}for r in m['sourceBefore']['files']];assert current==m['sourceBefore']['files'];head=subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'],text=True).strip();assert head==m['sourceBefore']['commit'];status=subprocess.check_output(['git','-C',str(repo),'status','--porcelain','--','src','public','scripts','tests','package.json','package-lock.json','vite.config.ts'],text=True);assert status==''
frames=sorted((root/'frames').glob('*.png'));assert len(frames)==len(m['frames'])==928
video=root/'failed-encounter-with-complete-circuits.mp4';cmd=['ffmpeg','-hide_banner','-loglevel','error','-y','-framerate','20','-i',str(root/'frames/%05d.png'),'-c:v','libx264','-pix_fmt','yuv420p','-movflags','+faststart',str(video)];subprocess.run(cmd,check=True);subprocess.run(['ffmpeg','-v','error','-i',str(video),'-f','null','-'],check=True);probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_streams','-show_format','-of','json',str(video)]));assert int(probe['streams'][0]['nb_read_frames'])==928
out={'recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'disclosure':'Original recorder manifest remains FAILED and unchanged: both opposite circuits completed by frame640, then the stationary pilot died at927 with2 enemies remaining. No second encounter completion claimed. Video was encoded after failure from all928 retained frames. Separate postfailure source check confirms same current source bytes, not a retroactive sourceAfter field. Successful prior encounter remains separate at the same source.','manifestSha256':hashfile(root/'manifest.json'),'sourceAfterFailure':{'commit':head,'status':status,'files':current},'command':cmd,'video':{'file':video.name,'sha256':hashfile(video),'probe':probe},'frames':[{'file':str(p.relative_to(root)),'sha256':hashfile(p)}for p in frames]};(root/'postfailure-provenance.json').write_text(json.dumps(out,indent=2)+'\n');print('Preserved',len(frames),'frames',out['video']['sha256'])
